// Compact binary format for the hero tooth (generated by scripts/build-tooth.mjs, decoded in the browser).
// Positions are int16 normalized to the bounding box and normals int8 — both used directly as normalized
// GPU attributes, so the browser does no decoding work.
//
// Layout (little-endian): "TOTH" | u8 version | u8 index bytes | u16 pad | u32 vertices | u32 indices |
// f32[3] min | f32[3] max | i16[3V] positions | i8[3V] normals | pad to index size | u16/u32[I] indices
export type ToothMesh = {
  positions: Int16Array;
  normals: Int8Array;
  indices: Uint16Array | Uint32Array;
  min: [number, number, number];
  max: [number, number, number];
};

const MAGIC = 0x48544f54; // "TOTH"
const HEADER = 40;

export function encodeTooth(mesh: ToothMesh): ArrayBuffer {
  const vertices = mesh.positions.length / 3;
  const indexBytes = mesh.indices.BYTES_PER_ELEMENT;
  const normalsEnd = HEADER + mesh.positions.byteLength + mesh.normals.byteLength;
  const indexOffset = Math.ceil(normalsEnd / indexBytes) * indexBytes;
  const buffer = new ArrayBuffer(indexOffset + mesh.indices.byteLength);
  const view = new DataView(buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint8(4, 1);
  view.setUint8(5, indexBytes);
  view.setUint32(8, vertices, true);
  view.setUint32(12, mesh.indices.length, true);
  [...mesh.min, ...mesh.max].forEach((v, i) => view.setFloat32(16 + i * 4, v, true));
  new Int16Array(buffer, HEADER, vertices * 3).set(mesh.positions);
  new Int8Array(buffer, HEADER + mesh.positions.byteLength, vertices * 3).set(mesh.normals);
  const Indices = indexBytes === 2 ? Uint16Array : Uint32Array;
  new Indices(buffer, indexOffset, mesh.indices.length).set(mesh.indices);
  return buffer;
}

export function decodeTooth(buffer: ArrayBuffer): ToothMesh {
  const view = new DataView(buffer);
  if (buffer.byteLength < HEADER || view.getUint32(0, true) !== MAGIC) throw new Error("not a tooth model");
  const indexBytes = view.getUint8(5);
  const vertices = view.getUint32(8, true);
  const indexCount = view.getUint32(12, true);
  const floats = [0, 1, 2, 3, 4, 5].map((i) => view.getFloat32(16 + i * 4, true));
  const normalsOffset = HEADER + vertices * 6;
  const indexOffset = Math.ceil((normalsOffset + vertices * 3) / indexBytes) * indexBytes;
  const Indices = indexBytes === 2 ? Uint16Array : Uint32Array;
  return {
    positions: new Int16Array(buffer, HEADER, vertices * 3),
    normals: new Int8Array(buffer, normalsOffset, vertices * 3),
    indices: new Indices(buffer, indexOffset, indexCount),
    min: [floats[0], floats[1], floats[2]],
    max: [floats[3], floats[4], floats[5]],
  };
}
